const RUN = makeColony(COLONY);
export const examples = [{"q":"which of these is a programming language: Spanish, Unix shell or Photoshop","expect":{"contains":["Unix shell"],"notContains":["Spanish","Photoshop"],"notRefusal":true}},{"q":"which of these is a programming language: Visual Fortran, Hebrew or Windows","expect":{"contains":["Visual Fortran"],"notContains":["Hebrew","Windows"],"notRefusal":true}},{"q":"pick a programming language from Dropbox, chomski or English","expect":{"contains":["chomski"],"notContains":["Dropbox","English"],"notRefusal":true}},{"q":"pick a programming language from Portuguese, Magma or Hindi","expect":{"contains":["Magma"],"notContains":["Hindi","Portuguese"],"notRefusal":true}},{"q":"among ML, Turkish or English, which one is a programming language","expect":{"contains":["ML"],"notContains":["English","Turkish"],"notRefusal":true}},{"q":"pick a programming language from Wikipedia, German or Gibiane","expect":{"contains":["Gibiane"],"notContains":["German","Wikipedia"],"notRefusal":true}},{"q":"pick a programming language from MicroScript, Instagram or French","expect":{"contains":["MicroScript"],"notContains":["French","Instagram"],"notRefusal":true}},{"q":"which of these is a programming language: Wikipedia, Leda or Windows","expect":{"contains":["Leda"],"notContains":["Windows","Wikipedia"],"notRefusal":true}},{"q":"which of these is a programming language: Excel, NPL or Swahili","expect":{"contains":["NPL"],"notContains":["Swahili","Excel"],"notRefusal":true}},{"q":"among Turkish, Batch (Windows/Dos) or PowerPoint, which one is a programming language","expect":{"contains":["Batch (Windows/Dos)"],"notContains":["Turkish","PowerPoint"],"notRefusal":true}},{"q":"which of these is a programming language: Boomerang, Polish or Windows","expect":{"contains":["Boomerang"],"notContains":["Windows","Polish"],"notRefusal":true}},{"q":"which of these is a programming language: ISPF, Hindi or Mandarin","expect":{"contains":["ISPF"],"notContains":["Mandarin","Hindi"],"notRefusal":true}},{"q":"which of these is a programming language: S, Hebrew or Korean","expect":{"contains":["S"],"notContains":["Korean","Hebrew"],"notRefusal":true}},{"q":"pick a programming language from BPEL, PowerPoint or German","expect":{"contains":["BPEL"],"notContains":["German","PowerPoint"],"notRefusal":true}},{"q":"among Korean, Oz or Hebrew, which one is a programming language","expect":{"contains":["Oz"],"notContains":["Hebrew","Korean"],"notRefusal":true}},{"q":"which of these is a programming language: Bengali, Greek or SA-C","expect":{"contains":["SA-C"],"notContains":["Bengali","Greek"],"notRefusal":true}},{"q":"pick a programming language from Polish, Minecraft or High Level Assembly","expect":{"contains":["High Level Assembly"],"notContains":["Polish","Minecraft"],"notRefusal":true}},{"q":"among English, Italian or SETL, which one is a programming language","expect":{"contains":["SETL"],"notContains":["Italian","English"],"notRefusal":true}},{"q":"among Portuguese, Italian or Model 204, which one is a programming language","expect":{"contains":["Model 204"],"notContains":["Portuguese","Italian"],"notRefusal":true}},{"q":"pick a programming language from GPSS, German or Arabic","expect":{"contains":["GPSS"],"notContains":["Arabic","German"],"notRefusal":true}}];
export const colony = Object.freeze({ cells: COLONY.length, kernel: KERNEL_VERSION });
/** The answer of the first cell of the colony that answers q, or null. */
export function answer(q) { return RUN.answer(String(q ?? '')); }
/** Whether a cell of the colony answers q. */
export function can(q) { return answer(q) !== null; }
